def pv(s):
    out = []
    for tok in s.strip().strip("|").split("|"):
        if not tok:
            continue
        x, y, z = tok.split(",")
        out.append((float(x) * SCALE, float(y) * SCALE, float(z) * SCALE))
    return out


def pf(s):
    out = []
    for tok in s.strip().strip("|").split("|"):
        if not tok:
            continue
        out.append(tuple(int(i) for i in tok.split(",")))
    return out


def material(name, color):
    mat = bpy.data.materials.get(name)
    if mat is None:
        mat = bpy.data.materials.new(name)
        mat.use_nodes = True
        bsdf = mat.node_tree.nodes.get("Principled BSDF")
        if bsdf is not None:
            bsdf.inputs["Base Color"].default_value = (*color, 1.0)
        mat.diffuse_color = (*color, 1.0)
    return mat


def collection(name):
    coll = bpy.data.collections.get(name)
    if coll is None:
        coll = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(coll)
    return coll


def build_mesh(name, verts, faces, mat):
    me = bpy.data.meshes.new(name)
    me.from_pydata(verts, [], faces)
    me.validate(verbose=False)
    bm = bmesh.new()
    bm.from_mesh(me)
    bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=MERGE_DIST)
    bmesh.ops.dissolve_limit(bm, angle_limit=DISSOLVE_ANGLE,
                             use_dissolve_boundaries=False,
                             verts=bm.verts, edges=bm.edges)
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(me)
    bm.free()
    me.update()
    me.materials.append(mat)
    return me


def main():
    coll = collection(ROOT_NAME)
    mat_b = material("frame-hor_black", COL_BLACK)
    mat_g = material("frame-hor_gray", COL_GRAY)

    root = bpy.data.objects.new(ROOT_NAME + "_root", None)
    root.empty_display_type = "PLAIN_AXES"
    root.empty_display_size = 80.0 * SCALE
    coll.objects.link(root)

    n_obj = 0

    # --- black structural members (shared mesh data per unique shape) ---
    for grp in BLACK:
        verts = pv(grp["v"])
        faces = pf(grp["f"])
        assert len(verts) == grp["nv"], "%s verts %d!=%d" % (grp["name"], len(verts), grp["nv"])
        assert len(faces) == grp["nf"], "%s faces %d!=%d" % (grp["name"], len(faces), grp["nf"])
        me = build_mesh(grp["name"], verts, faces, mat_b)
        for k, off in enumerate(grp["off"]):
            nm = grp["name"] if len(grp["off"]) == 1 else "%s_%02d" % (grp["name"], k + 1)
            ob = bpy.data.objects.new(nm, me)            # linked duplicate (shared data)
            coll.objects.link(ob)
            ob.parent = root
            ob.location = (off[0] * SCALE, off[1] * SCALE, off[2] * SCALE)
            n_obj += 1



    print("Built block '%s': %d objects (%d black groups + 8 connectors)"
          % (ROOT_NAME, n_obj, len(BLACK)))


if __name__ == "__main__":
    main()
